const input = $input.first();
const json = input.json;
let issueKey = '';
let project = '';
let skill = '';

if (json.params) {
  issueKey = json.params.issueKey || '';
  project = json.params.project || '';
  skill = json.params.skill || '';
} else if (json.body) {
  issueKey = json.body.issueKey || '';
  project = json.body.project || '';
  skill = json.body.skill || '';
}

if (!issueKey && json.issueKey) {
  issueKey = json.issueKey;
}

if (!issueKey) {
  return [{
    json: {
      error: 'Thiếu tham số issueKey.',
      issueKey: '',
      project: project,
      skill: skill
    }
  }];
}

return [{
  json: {
    issueKey: issueKey.toUpperCase(),
    project: (project || '').trim(),
    skill: (skill || 'run-test').trim()
  }
}];

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const input = $input.first();
const issueKey = (input.json.issueKey || '').toUpperCase();
const project = input.json.project || '';

if (input.json.error || !issueKey) {
  return [{
    json: {
      stdout: '',
      stderr: input.json.error || 'Thiếu tham số issueKey.',
      exitCode: 1,
      error: { message: input.json.error || 'Thiếu tham số issueKey.' }
    }
  }];
}

let cwd = $env.AGENT_WORKSPACE_DIR || process.cwd();

// Nếu có chỉ định project, tìm thư mục project từ projects.json nếu tồn tại
if (project) {
  try {
    const projectsFile = path.resolve(cwd, 'projects.json');
    if (fs.existsSync(projectsFile)) {
      const projects = JSON.parse(fs.readFileSync(projectsFile, 'utf8'));
      if (projects[project]) {
        cwd = projects[project];
      }
    }
  } catch (e) {}
}

const testDir = path.resolve(cwd, 'workspace', issueKey, 'test');

if (!fs.existsSync(testDir)) {
  return [{
    json: {
      stdout: '',
      stderr: 'Không tìm thấy thư mục kiểm thử: workspace/' + issueKey + '/test trên hệ thống.',
      exitCode: 4,
      error: { message: 'Thư mục kiểm thử không tồn tại: workspace/' + issueKey + '/test' }
    }
  }];
}

let testTarget = '';
try {
  const files = fs.readdirSync(testDir);
  const pyTestFiles = files.filter(f => f.startsWith('test_') && f.endsWith('.py'));
  const anyPyFiles = files.filter(f => f.endsWith('.py'));

  if (pyTestFiles.length > 0) {
    testTarget = path.join(testDir, 'test_*.py');
  } else if (anyPyFiles.length > 0) {
    testTarget = path.join(testDir, anyPyFiles[0]);
  } else {
    return [{
      json: {
        stdout: '',
        stderr: 'Không tìm thấy file Python test (*.py) nào trong workspace/' + issueKey + '/test.',
        exitCode: 4,
        error: { message: 'Không có file test nào trong thư mục.' }
      }
    }];
  }
} catch (e) {
  return [{
    json: {
      stdout: '',
      stderr: 'Lỗi truy xuất thư mục kiểm thử: ' + e.message,
      exitCode: 1,
      error: { message: e.message }
    }
  }];
}

const command = 'pytest ' + testTarget + ' -v --tb=short';

try {
  const result = execSync(command, { encoding: 'utf-8', cwd: cwd, timeout: 60000 });
  return [{ json: { stdout: result, stderr: '', exitCode: 0 } }];
} catch (err) {
  return [{
    json: {
      stdout: err.stdout || '',
      stderr: err.stderr || err.message,
      exitCode: err.status || 1,
      error: { message: err.message }
    }
  }];
}

const input = $input.first();
const extractNode = $('Extract issueKey').first().json;
const issueKey = extractNode.issueKey || '';
const project = extractNode.project || '';
const targetLabel = project ? (project + ' / ' + issueKey) : issueKey;

// Xử lý lỗi Extract
if (!issueKey || extractNode.error) {
  return [{
    json: {
      success: false,
      message: '🚨 **[QA Automation Lỗi]** Không tìm thấy issueKey hợp lệ trong yêu cầu.\n' +
               '> Cú pháp hợp lệ: `/agent [project] run-test <issueKey>` (trong đó [project] là tùy chọn).'
    }
  }];
}

// Xử lý kết quả lệnh Execute Command
const execRes = input.json;
let success = true;
let outputText = execRes.stdout || '';
let errText = execRes.stderr || '';

if (execRes.error || (execRes.exitCode !== undefined && execRes.exitCode !== 0)) {
  success = false;
}

// Rút gọn output nếu quá dài
let logSnippet = (outputText + '\n' + errText).trim();
if (logSnippet.length > 2500) {
  logSnippet = logSnippet.substring(logSnippet.length - 2500);
}

const statusIcon = success ? '✅' : '❌';
const statusText = success ? 'Thành công (Passed)' : 'Thất bại (Failed)';

const message = '🚀 **[QA Automation]** Kết quả chạy kiểm thử cho vé **' + targetLabel + '**:\n' +
                '- Trạng thái: ' + statusIcon + ' **' + statusText + '**\n\n' +
                '```text\n' + logSnippet + '\n```';

return [{ json: { success, message, issueKey, project } }];
